contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint depositAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmount)); require(depositAmount <= 1000000000000000000000000000000);
        require(address(this).balance >= depositAmount);

        // Observe before deposit
        uint beforeCBalance = address(c).balance;

        // Perform deposit: top-level state-changing call
        c.deposit{value: depositAmount}(); if (__ESBMC_reverted()) return;

        // Observe immediately after deposit
        uint afterCBalance = address(c).balance;

        // Attempt withdrawAll and record whether it reverted
        bool didRevert;
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            didRevert = true;
        } else {
            didRevert = false;
        }

        // Final observed contract balance
        uint finalCBalance = address(c).balance;

        // Assert the general rule:
        // 1) deposit increased c.balance exactly by depositAmount
        // 2) if withdrawAll reverted then final balance equals afterCBalance
        // 3) otherwise final balance is <= afterCBalance and at least afterCBalance - depositAmount
        assert(
            afterCBalance == beforeCBalance + depositAmount
            && (
                (didRevert && finalCBalance == afterCBalance)
                || (!didRevert && finalCBalance <= afterCBalance && finalCBalance + depositAmount >= afterCBalance)
            )
        );
    }

    receive() external payable {}
}

